window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9714fb22e398a161"]={"versions": [{"id": "FIG-9714fb22e398a161", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses innerhalb der Funktion <code>E2E_P06Forward()</code> des AUTOSAR E2E-Protokolls (Profile 6). Es modelliert die funktionale Vorbedingungs- und Eingangsvalidierung (<code>Verify inputs of the forward function</code>) vor der eigentlichen Weiterleitungsverarbeitung von Daten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontext</strong>: <code>E2E_P06Forward()</code>\n</li><li><strong>Eingangsparameter / Entitäten</strong>:\n<ul class=\"fig-list\"><li><code>Config</code>: Zeiger auf die statische Konfigurationsstruktur des E2E Profile 6 (enthält <code>MinDataLength</code>, <code>MaxDataLength</code> in Bits).\n</li><li><code>State</code>: Zeiger auf die Zustandsstruktur der Forward-Funktion.\n</li><li><code>Data</code>: Zeiger auf das zu prüfende und weiterzuleitende Datenfeld.\n</li><li><code>ForwardStatus</code>: Zeiger auf den Statuswert bzw. den Weiterleitungsstatus.\n</li><li><code>Length</code>: Länge des Nutzdatenpuffers in Bytes.\n</li></ul>\n</li><li><strong>Konstanten / Enumeratoren</strong>: <code>NULL</code>, <code>E2E_P_NONEWDATA</code>.\n</li><li><strong>Knotenelemente</strong>: Ein initialer Startknoten, zwei Verzweigungsknoten (Decision Nodes) mit Guards und drei Endknoten (Aktivitätsendknoten).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Start</strong>: Ausführung startet am initialen Pseudo-Zustand.\n</li><li><strong>Erste Validierungsstufe (Zeigerprüfung)</strong>:\n<ul class=\"fig-list\"><li>Bedingung: <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL) &amp;&amp; (ForwardStatus != NULL)</code>.\n</li><li>Bei <code>[FALSE]</code>: Verzweigung zum linken Endknoten (Fehlerfall ungültiger Zeiger / Nullzeiger).\n</li><li>Bei <code>[TRUE]</code>: Übergang zur zweiten Validierungsstufe.\n</li></ul>\n</li><li><strong>Zweite Validierungsstufe (Längen- und Statusprüfung)</strong>:\n<ul class=\"fig-list\"><li>Bedingung: <code>(Length &gt;= Config-&gt;MinDataLength/8) &amp;&amp; (Length &lt;= Config-&gt;MaxDataLength/8) &amp;&amp; (ForwardStatus != E2E_P_NONEWDATA)</code>.\n</li><li>Bei <code>[FALSE]</code>: Verzweigung zum rechten Endknoten (Fehlerfall unzulässige Pufferlänge oder Status <code>E2E_P_NONEWDATA</code>).\n</li><li>Bei <code>[TRUE]</code>: Übergang zum mittleren Endknoten (<code>input</code>), womit die Validierung erfolgreich abgeschlossen ist und die reguläre Weiterleitungsausführung fortgesetzt werden kann.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Die Implementierung von <code>E2E_P06Forward()</code> muss zwingend eine strikte zweistufige Vorabprüfung vornehmen.\n</li><li>Zuerst müssen sämtliche übergebenen Referenzen auf Nullzeiger (<code>NULL</code>) geprüft werden, um Speicherzugriffsfehler abzufangen.\n</li><li>Nach erfolgreicher Zeigerprüfung muss verifiziert werden, dass die Bytelänge <code>Length</code> innerhalb des durch <code>Config-&gt;MinDataLength/8</code> und <code>Config-&gt;MaxDataLength/8</code> definierten Intervalls liegt.\n</li><li>Zudem muss sichergestellt sein, dass <code>ForwardStatus</code> ungleich <code>E2E_P_NONEWDATA</code> ist, da ohne neue Daten keine Weiterleitung stattfinden darf.\n</li><li>Schlägt eine der Prüfungen fehl, bricht die Funktionsausführung ab und liefert den entsprechenden Fehlerstatus zurück.\n</li></ul>"}, {"id": "FIG-f3888203aedb6593", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses innerhalb der Funktion <code>E2E_P06Forward()</code> des AUTOSAR E2E-Protokolls (Profile 6). Es modelliert die funktionale Vorbedingungs- und Eingangsvalidierung (<code>Verify inputs of the forward function</code>) vor der eigentlichen Weiterleitungsverarbeitung von Daten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontext</strong>: <code>E2E_P06Forward()</code>\n</li><li><strong>Eingangsparameter / Entitäten</strong>:\n<ul class=\"fig-list\"><li><code>Config</code>: Zeiger auf die statische Konfigurationsstruktur des E2E Profile 6 (enthält <code>MinDataLength</code>, <code>MaxDataLength</code> in Bits).\n</li><li><code>State</code>: Zeiger auf die Zustandsstruktur der Forward-Funktion.\n</li><li><code>Data</code>: Zeiger auf das zu prüfende und weiterzuleitende Datenfeld.\n</li><li><code>ForwardStatus</code>: Zeiger auf den Statuswert bzw. den Weiterleitungsstatus.\n</li><li><code>Length</code>: Länge des Nutzdatenpuffers in Bytes.\n</li></ul>\n</li><li><strong>Konstanten / Enumeratoren</strong>: <code>NULL</code>, <code>E2E_P_NONEWDATA</code>.\n</li><li><strong>Knotenelemente</strong>: Ein initialer Startknoten, zwei Verzweigungsknoten (Decision Nodes) mit Guards und drei Endknoten (Aktivitätsendknoten).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Start</strong>: Ausführung startet am initialen Pseudo-Zustand.\n</li><li><strong>Erste Validierungsstufe (Zeigerprüfung)</strong>:\n<ul class=\"fig-list\"><li>Bedingung: <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL) &amp;&amp; (ForwardStatus != NULL)</code>.\n</li><li>Bei <code>[FALSE]</code>: Verzweigung zum linken Endknoten (Fehlerfall ungültiger Zeiger / Nullzeiger).\n</li><li>Bei <code>[TRUE]</code>: Übergang zur zweiten Validierungsstufe.\n</li></ul>\n</li><li><strong>Zweite Validierungsstufe (Längen- und Statusprüfung)</strong>:\n<ul class=\"fig-list\"><li>Bedingung: <code>(Length &gt;= Config-&gt;MinDataLength/8) &amp;&amp; (Length &lt;= Config-&gt;MaxDataLength/8) &amp;&amp; (ForwardStatus != E2E_P_NONEWDATA)</code>.\n</li><li>Bei <code>[FALSE]</code>: Verzweigung zum rechten Endknoten (Fehlerfall unzulässige Pufferlänge oder Status <code>E2E_P_NONEWDATA</code>).\n</li><li>Bei <code>[TRUE]</code>: Übergang zum mittleren Endknoten (<code>input</code>), womit die Validierung erfolgreich abgeschlossen ist und die reguläre Weiterleitungsausführung fortgesetzt werden kann.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Die Implementierung von <code>E2E_P06Forward()</code> muss zwingend eine strikte zweistufige Vorabprüfung vornehmen.\n</li><li>Zuerst müssen sämtliche übergebenen Referenzen auf Nullzeiger (<code>NULL</code>) geprüft werden, um Speicherzugriffsfehler abzufangen.\n</li><li>Nach erfolgreicher Zeigerprüfung muss verifiziert werden, dass die Bytelänge <code>Length</code> innerhalb des durch <code>Config-&gt;MinDataLength/8</code> und <code>Config-&gt;MaxDataLength/8</code> definierten Intervalls liegt.\n</li><li>Zudem muss sichergestellt sein, dass <code>ForwardStatus</code> ungleich <code>E2E_P_NONEWDATA</code> ist, da ohne neue Daten keine Weiterleitung stattfinden darf.\n</li><li>Schlägt eine der Prüfungen fehl, bricht die Funktionsausführung ab und liefert den entsprechenden Fehlerstatus zurück.\n</li></ul>"}], "trans": [{"from": "FIG-9714fb22e398a161", "to": "FIG-f3888203aedb6593", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
